INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(119275, 'ruRU', '', 'Это не совсем решение, не так ли? Попробуй активировать ящик снова, чтобы попытаться ещё раз.', 24330),
(119282, 'ruRU', '', 'Превосходно. Испытаем наше заклинание?', 24330),
(119283, 'ruRU', '', 'Нас может быть немного, но Легион научится бояться Стражи.', 24330),
(119285, 'ruRU', '', 'Начнём ритуал немедленно.', 24330),
(119287, 'ruRU', '', 'Я не знаю. Но мы обязаны попытаться ради нашего друга.', 24330),
(119291, 'ruRU', '', 'Встретимся в Святилище Порядка. Мне нужно подготовиться к церемонии.', 24330),
(119293, 'ruRU', '', 'Elun''falah shalar.', 24330),
(119294, 'ruRU', '', 'Ishnu-talah Kaldorei!', 24330),
(119297, 'ruRU', '', 'Мы прибыли к Вратам Демонического Пламени вскоре после того, как покинули часовню Последней Надежды. Этот журнал свидетельствует о нашем путешествии.', 24330),
(119298, 'ruRU', '', 'Как и обещала, Делас привела жрецов Конклава присоединиться к битве. Наши силы неплохо сработались.', 24330),
(119299, 'ruRU', '', 'Жрецы также ищут Балназара. Их лидер, Пророк Велен, увидел видение, в котором повелитель ужаса обрушивает разрушение на Азерот.', 24330),
(119300, 'ruRU', '', 'Легион пока не подозревает о нашем присутствии. Их предводительница, Королева выводка Арамис, каждый день бродит по лагерю.', 24330),
(119301, 'ruRU', '', 'Мы атакуем завтра. Пусть Свет направляет нас.', 24330),
(119302, 'ruRU', '', 'Мы недооценили коварство Легиона! После нашей атаки портал вспыхнул жизнью. Балназар прибыл и прорвал нашу оборону.', 24330),
(119303, 'ruRU', '', 'Мы всё ещё живы, но нас проводят через портал... в их родной мир. Что ждёт нас на той стороне?', 24330),
(119304, 'ruRU', '', 'Я на мгновение освободился. Прошу, если кто-то найдёт это — ты наша единственная надежда на спасение.', 24330),
(119309, 'ruRU', '', 'Доблесть Одина соперничает лишь с его аппетитом. Истинный воин.', 24330),
(119317, 'ruRU', '', 'Готовься к бою, защитник. Даже Валарьяры не смеют подходить так близко к владениям Хелии.', 24330),
(119321, 'ruRU', '', 'Я понимаю, муж мой. Но если Майев отпустила их, значит ситуация даже хуже, чем мы думаем.', 24330),
(119324, 'ruRU', '', 'Благодарю. Мы не могли допустить, чтобы священная реликвия моего народа попала в руки такого монстра!', 24330),
(119326, 'ruRU', '', 'Вот она! Он''ара хочет, чтобы ты следовал за ней.', 24330),
(119328, 'ruRU', '', 'Я рад, что Он''ара дала своё благословение. Я боялся, что действия Кровавого Тотема разозлили её. Теперь мы можем отправляться в Штормхейм!', 24330),
(119330, 'ruRU', '', 'Думаю, она предлагает помощь. Посмотри на её крыло— ОХ! Спасибо!', 24330),
(119331, 'ruRU', '', 'Верховный лорд! Сюда!', 24330),
(119341, 'ruRU', '', 'Много благородных духов бродит среди живых, но проклятые последователи лорда Воронья Вершина не подлежат искуплению. Тебе лучше победить их, прежде чем они соберутся и атакуют Брейдсбрук всей силой.', 24330),
(119342, 'ruRU', '', 'Силы духов были ослаблены... на время. Может ли то, что уже мёртво, по-настоящему умереть?', 24330),
(119343, 'ruRU', '', 'На этот раз эти духи перешли все границы! Они ловят и убивают этих милых маленьких лунокрылых фей-драконов. Что ж, иди! Спаси их!', 24330),
(119344, 'ruRU', '', 'Фей-драконы такие драгоценные! Моему сердцу радостно видеть их защищёнными.', 24330),
(119353, 'ruRU', '', 'Пожалей жителей Брейдснбрука! Они покинули Гилнеас, прежде чем стать жертвами проклятия ворген, но теперь сталкиваются с жестокостью приспешников лорда Воронья Вершина. Их деревне нужна твоя защита.', 24330),
(119354, 'ruRU', '', 'Хотя у нас есть разногласия, те, кто в Брейдснбруке, всё же мой народ. Было мило с твоей стороны помочь им.', 24330),
(119355, 'ruRU', '', 'Мерзкий яд просачивается в воды Туманной Долины. Я чувствую нутром, что это должно быть дело рук развращённого друида. Найди осквернителя и прекрати эту напасть.', 24330),
(119356, 'ruRU', '', 'Как кто-то мог настолько искривиться внутри, чтобы заразить такое прекрасное озеро? По крайней мере, ты всё исправил.', 24330),
(119357, 'ruRU', '', 'Пришёл Листобород Сказитель! Это старая душа, что рассказывает захватывающую историю о Войне древних. Слушай внимательно, и ты можешь выучить ценные уроки, что помогут тебе в борьбе против Легиона.', 24330),
(119358, 'ruRU', '', 'Война древних видела множество великих битв, подобных той, что ты только что пережил. Тогда потребовались совместные усилия всех защитников Азерота, чтобы победить демонов — как и сейчас.', 24330),
(119359, 'ruRU', '', 'Сами корни Мирового Древа заражены Кошмаром. Очисти Шала''нир от заразы, что захватила его.', 24330),
(119360, 'ruRU', '', 'Однажды Шала''нир будет возвращён, а корни Мирового Древа защищены. Мы не должны отдыхать, пока этот день не настанет над Вал''шарой!', 24330),
(119361, 'ruRU', '', 'Прислужники Кошмара продолжают осквернять Долину Лунного Когтя. Дай им отпор, защитник!', 24330),
(119362, 'ruRU', '', 'Долину всё ещё терзает тьма, но ты вернул в неё луч надежды. Благодарю тебя.', 24330),
(119363, 'ruRU', '', 'Наши союзники-хранители и дриады были искривлены коварной силой Кошмара. Ты должен прекратить их страдания.', 24330),
(119364, 'ruRU', '', 'Потеря слуг Сна разбивает мне сердце, но, по крайней мере, они обрели покой. За это я благодарю тебя.', 24330);
